"""Loader for versioned local maintainer profiles; see README.md."""

import importlib


def load_config(text: str) -> dict:
    """Load a local maintainer profile.

    Each non-blank, non-comment line is split at its first ``=`` into a key and a
    Python expression. Every expression is evaluated; non-``plugin`` entries are
    collected into ``settings``. The ``plugin`` expression evaluates to a module
    name whose ``Transform`` class is imported and instantiated.
    """
    settings: dict = {}
    plugin = None

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue

        key, sep, value = line.partition("=")
        if not sep:
            continue

        key = key.strip()
        result = eval(value.strip())  # noqa: S307 - trusted local profiles only

        if key == "plugin":
            module = importlib.import_module(result)
            plugin = module.Transform()
        else:
            settings[key] = result

    return {"settings": settings, "plugin": plugin}
